    "faqs": [
      {
        "q": "Q1. What is Meta Ads Management?",
        "a": "Meta Ads Management is the planning, setup, monitoring, and optimisation of paid advertising campaigns across supported Meta platforms, including Facebook and Instagram."
      },
      {
        "q": "Q2. Are Facebook Ads and Instagram Ads included?",
        "a": "They can both be included when specified in your selected scope. The platforms, placements, and campaign objectives depend on your requirements and account eligibility."
      },
      {
        "q": "Q3. How much budget do I need for Meta Ads?",
        "a": "There is no single budget suitable for every business. The appropriate starting budget depends on your objective, market, audience, offer, competition, and testing needs. Your management fee and advertising spend are separate unless the quotation explicitly states otherwise."
      },
      {
        "q": "Q4. Does E-COMET guarantee leads or sales?",
        "a": "No. Advertising results depend on multiple factors, including the offer, audience, creative, competition, landing page, budget, and sales follow-up. We focus on structured campaign management, measurement, and informed optimisation."
      },
      {
        "q": "Q5. Can Meta Ads help my local business?",
        "a": "Yes, Meta Ads may be suitable for local businesses seeking awareness, enquiries, bookings, or promotion of services and offers, depending on the business category and campaign objective."
      },
      {
        "q": "Q6. Can you run ads for my e-commerce store?",
        "a": "Yes, subject to the store, products, account setup, destination, and advertising policies being suitable. We can discuss the campaign structure and tracking requirements during consultation."
      },
      {
        "q": "Q7. Do I need a website to run Meta Ads?",
        "a": "Not always. Depending on the campaign objective and available features, advertisements may direct users to supported lead forms, messaging destinations, or other permitted destinations. A website or landing page may be necessary for particular conversion goals."
      },
      {
        "q": "Q8. Do you create ad images and videos?",
        "a": "Creative support can be included within a defined package scope. Advanced design, photography, video production, animation, and extensive creative batches may require a separate quotation."
      },
      {
        "q": "Q9. Can you set up Meta Pixel and conversion tracking?",
        "a": "We can review tracking requirements and coordinate suitable setup. Implementation depends on your website platform, permissions, technical requirements, consent arrangements, and the agreed scope."
      },
      {
        "q": "Q10. How long does it take to launch a campaign?",
        "a": "The timeline depends on account access, asset readiness, campaign complexity, tracking requirements, client approvals, and Meta's review process. We will outline the expected preparation timeline after reviewing your requirements, but platform approval timing is outside our control."
      },
      {
        "q": "Q11. Will you manage my advertising budget?",
        "a": "We can configure and monitor campaign budgets within the approved scope. Advertising spend is generally paid to Meta through the client's advertising account and is separate from E-COMET's management fee. Payment arrangements will be confirmed in the quotation."
      },
      {
        "q": "Q12. Do I need to give you access to my Facebook and Instagram accounts?",
        "a": "We need appropriate permissions to manage the agreed work. Access should be provided through Meta's supported business access and permission tools wherever possible. Do not share personal passwords."
      },
      {
        "q": "Q13. Will I receive campaign reports?",
        "a": "Yes. Reporting is included according to the agreed package. The report format, frequency, and metrics will be defined in your quotation."
      },
      {
        "q": "Q14. Can you manage both Meta Ads and organic social media?",
        "a": "Yes. Paid advertising and organic social media management are separate services that can be combined through an integrated plan when required."
      },
      {
        "q": "Q15. What if my ad account is restricted or my ads are rejected?",
        "a": "We can review available account information and help identify possible next steps within the agreed scope. Meta controls its account restrictions, reviews, and approval decisions. We cannot guarantee reinstatement or ad approval."
      },
      {
        "q": "Q16. Are there any industries you cannot advertise?",
        "a": "Some products, services, claims, and audience practices are restricted or prohibited by Meta. We assess campaign suitability before proceeding and cannot assist with campaigns that violate platform policies or applicable law."
      },
      {
        "q": "Q17. How do I choose between Orbit, Nova, and Cosmic?",
        "a": "The right option depends on your campaign complexity, creative requirements, audience strategy, reporting needs, and desired management scope. We can recommend a suitable option after a consultation."
      },
      {
        "q": "Q18. How can I get a quotation?",
        "a": "Submit the enquiry form below. Our team can review your requirements and discuss a suitable campaign scope before preparing a custom quotation."
      }
    ],
