    "faqs": [
      {
        "q": "Q1. What is Google Ads Management?",
        "a": "Google Ads Management involves planning, setting up, monitoring, and optimising advertising campaigns through Google's advertising platform according to defined business objectives."
      },
      {
        "q": "Q2. Which types of Google Ads do you manage?",
        "a": "Depending on your requirements and eligibility, services may include Search, Display, YouTube, Shopping, Performance Max, and App campaigns."
      },
      {
        "q": "Q3. How much budget do I need for Google Ads?",
        "a": "The suitable budget depends on your industry, competition, target locations, search demand, objectives, and testing requirements. We can discuss a reasonable starting approach after understanding your business. Advertising spend and management fees are separate unless the quotation states otherwise."
      },
      {
        "q": "Q4. Does E-COMET guarantee leads, sales, or ROI?",
        "a": "No. Campaign results depend on factors such as competition, demand, budget, offer, landing page, tracking, and customer follow-up. We focus on structured campaign management and data-informed optimisation."
      },
      {
        "q": "Q5. Are Google Search Ads suitable for local businesses?",
        "a": "They may be suitable when customers search for the relevant products or services and the business can serve the targeted locations. Suitability depends on search demand, competition, and the business's requirements."
      },
      {
        "q": "Q6. Can you run Google Ads for an e-commerce store?",
        "a": "Yes, where the store and products are eligible. We can assess suitable Search, Shopping, or Performance Max approaches based on product data, website readiness, tracking, and account requirements."
      },
      {
        "q": "Q7. Do I need a website to run Google Ads?",
        "a": "Many campaigns use a website or landing page, particularly when the objective is website traffic, enquiries, or online purchases. Certain supported campaign formats may offer other destinations. We will assess the destination requirements before recommending a campaign."
      },
      {
        "q": "Q8. Do you create landing pages?",
        "a": "Landing-page review and recommendations can be included if specified. Landing-page design, development, extensive copywriting, and technical changes are separate services unless included in the quotation."
      },
      {
        "q": "Q9. Can you set up conversion tracking?",
        "a": "We can review tracking requirements and coordinate suitable implementation within the agreed scope. Technical work may require website developer access, analytics permissions, supported tools, and appropriate consent arrangements."
      },
      {
        "q": "Q10. How long does it take to launch Google Ads?",
        "a": "The timeline depends on account readiness, campaign complexity, keyword research, creative assets, website readiness, tracking, client approvals, and Google's review process. We will outline the expected preparation timeline after reviewing your requirements."
      },
      {
        "q": "Q11. Will Google Ads spend be included in your management fee?",
        "a": "Generally, advertising spend is paid to Google through the client's advertising account and is separate from E-COMET's management fee. The quotation will clarify all charges and payment responsibilities."
      },
      {
        "q": "Q12. Can you manage my existing Google Ads account?",
        "a": "Yes. We can review an existing account, assess current campaigns and tracking, and recommend a management plan based on your requirements."
      },
      {
        "q": "Q13. What if my ads are disapproved?",
        "a": "We can review available information and help identify possible corrective steps within the agreed scope. Google controls ad reviews, approval decisions, account restrictions, and appeal outcomes. Approval or reinstatement cannot be guaranteed."
      },
      {
        "q": "Q14. Do you manage Google Merchant Center?",
        "a": "Product feed and Merchant Center coordination may be included for eligible e-commerce campaigns when specified in the quotation. Complex integrations, extensive feed corrections, and other technical work may be scoped separately."
      },
      {
        "q": "Q15. Can Google Ads and SEO be managed together?",
        "a": "Yes. Paid advertising and SEO serve different purposes but can be coordinated as part of an integrated digital marketing plan."
      },
      {
        "q": "Q16. Will I receive performance reports?",
        "a": "Yes. Reporting is included according to the selected package. The reporting frequency, metrics, and format will be defined in the quotation."
      },
      {
        "q": "Q17. Do you manage advertising outside India?",
        "a": "International campaign management can be discussed according to target markets, account access, business eligibility, local requirements, and the agreed scope. Availability depends on the campaign and market involved."
      },
      {
        "q": "Q18. How do I choose between Orbit, Nova, and Cosmic?",
        "a": "The right option depends on the number and type of campaigns, complexity, tracking needs, creative requirements, and reporting expectations. We can recommend a suitable scope after consultation."
      }
    ],
