    "faqs": [
      {
        "q": "Q1. What is YouTube Ads Management?",
        "a": "YouTube Ads Management involves planning, setting up, monitoring, and optimising eligible video advertising campaigns through Google Ads."
      },
      {
        "q": "Q2. Can you run ads on YouTube for my business?",
        "a": "YouTube Ads may be suitable for product businesses, service providers, local businesses, e-commerce brands, and other eligible advertisers. Suitability depends on the campaign objective, content, audience, budget, and applicable policies."
      },
      {
        "q": "Q3. What types of YouTube Ads can you manage?",
        "a": "Depending on current availability and campaign eligibility, options may include skippable in-stream ads, non-skippable in-stream ads, in-feed video ads, Shorts ads, and other supported video advertising formats."
      },
      {
        "q": "Q4. Do I need a YouTube channel to run YouTube Ads?",
        "a": "Requirements depend on the selected campaign format and objective. Some campaigns use existing YouTube-hosted video assets, while other configurations may have additional requirements. We will review your account and campaign needs before confirming the setup."
      },
      {
        "q": "Q5. Do I need to create a video before starting?",
        "a": "Most video advertising campaigns require a suitable video asset. If you do not have one, E-COMET can discuss video production or editing as a separate service or as part of an explicitly agreed integrated package."
      },
      {
        "q": "Q6. Do you create videos for YouTube Ads?",
        "a": "Video creative planning and coordination can be included within the agreed scope. Professional filming, product photoshoots, advanced editing, animation, and voice-over may require a separate quotation."
      },
      {
        "q": "Q7. How much budget do I need for YouTube Ads?",
        "a": "The appropriate budget depends on your objective, target audience, competition, video creative, and market. We can discuss a suitable starting approach after understanding your requirements. Advertising spend and management fees are separate unless the quotation states otherwise."
      },
      {
        "q": "Q8. Can YouTube Ads generate leads and sales?",
        "a": "Eligible campaigns may be configured to support website visits, leads, sales, or other actions. Actual results depend on campaign setup, creative quality, offer, landing page, tracking, competition, and customer follow-up. Results cannot be guaranteed."
      },
      {
        "q": "Q9. Can YouTube Ads increase subscribers?",
        "a": "Advertising can promote eligible videos or channel content, but it does not guarantee subscribers, organic growth, monetisation eligibility, or long-term audience retention."
      },
      {
        "q": "Q10. Can you advertise my existing YouTube video?",
        "a": "An existing video may be suitable if it meets the requirements of the selected campaign and is eligible for advertising. We can review the asset and recommend an appropriate approach."
      },
      {
        "q": "Q11. Can you run ads on YouTube Shorts?",
        "a": "Shorts advertising may be available for eligible campaigns using suitable vertical creative. Availability and requirements depend on Google's current advertising options and account eligibility."
      },
      {
        "q": "Q12. Can you target a specific city or region?",
        "a": "Geographic targeting may be available depending on the campaign type and target market. Actual delivery depends on audience availability, settings, and Google's systems."
      },
      {
        "q": "Q13. Will you manage my Google Ads account?",
        "a": "We can manage the agreed campaigns using the required authorised access. Whenever possible, use supported account permissions rather than sharing personal passwords."
      },
      {
        "q": "Q14. Do you provide campaign reports?",
        "a": "Yes. Reporting is included according to the selected package. Metrics and frequency will be defined in the quotation."
      },
      {
        "q": "Q15. Is YouTube Ads spend included in your management fee?",
        "a": "Generally, advertising spend is paid to Google through the client's advertising account and is separate from E-COMET's management fee. The quotation will clarify all payment responsibilities."
      },
      {
        "q": "Q16. How long does it take to launch a campaign?",
        "a": "The timeline depends on account readiness, video asset availability, campaign complexity, tracking requirements, client approvals, and Google's review process. We will outline the expected preparation timeline after reviewing your requirements."
      },
      {
        "q": "Q17. What if my ad is rejected?",
        "a": "We can review the available information and help identify possible corrective steps within the agreed scope. Google controls ad review, approval, and account restriction decisions. Approval or reinstatement cannot be guaranteed."
      },
      {
        "q": "Q18. Can YouTube Ads and video production be managed together?",
        "a": "Yes. Campaign management and video production can be coordinated as an integrated solution when the required services and deliverables are included in the agreed quotation."
      },
      {
        "q": "Q19. Can YouTube Ads be combined with Google Search Ads or Meta Ads?",
        "a": "Yes. Multiple advertising channels can be coordinated when appropriate for your business goals, audience, budget, and measurement requirements."
      },
      {
        "q": "Q20. How do I choose between Orbit, Nova, and Cosmic?",
        "a": "The right package depends on campaign complexity, number of campaigns, creative requirements, audience strategy, tracking, and reporting needs. We can recommend a suitable scope after consultation."
      }
    ],
