    "faqs": [
      {
        "q": "Q1. What is Search Engine Optimization (SEO)?",
        "a": "SEO is the process of improving a website's content, structure, technical accessibility, and relevance to help search engines discover and understand its pages and potentially show them for relevant searches."
      },
      {
        "q": "Q2. How long does SEO take to show results?",
        "a": "The timeline varies according to website history, technical condition, competition, content quality, search demand, and the work being implemented. SEO is generally a longer-term activity, and no specific timeline or ranking outcome can be guaranteed."
      },
      {
        "q": "Q3. Can you guarantee a first-page Google ranking?",
        "a": "No. Search engines control their ranking systems, and rankings depend on many factors outside a service provider's control. We focus on structured optimisation, monitoring, and evidence-based recommendations."
      },
      {
        "q": "Q4. What is the difference between SEO and Google Ads?",
        "a": "SEO focuses on improving organic search visibility, while Google Ads involves paid advertising. SEO does not directly purchase organic rankings, and paid advertising does not guarantee better organic rankings. Both can be coordinated when suitable for your business."
      },
      {
        "q": "Q5. Do I need a website for SEO?",
        "a": "Traditional website SEO requires a website or other eligible web presence to optimise. If you do not have a website, E-COMET can discuss website development first and plan SEO requirements alongside it."
      },
      {
        "q": "Q6. Can SEO help a local business?",
        "a": "Yes. Local SEO may help improve the accuracy and discoverability of business information and relevant local pages. Actual local rankings depend on factors controlled by search platforms and the competitive environment."
      },
      {
        "q": "Q7. Do you provide E-Commerce SEO?",
        "a": "Yes. We can work on eligible online store pages, product and category content, internal linking, technical issues, and other agreed organic search requirements."
      },
      {
        "q": "Q8. Is marketplace listing SEO included?",
        "a": "Amazon, Flipkart, and other marketplace listing optimisation are separate from website SEO. These activities can be combined through an integrated quotation if your business requires both."
      },
      {
        "q": "Q9. Do you write blogs and website content?",
        "a": "Content planning and optimisation recommendations can be included in the agreed scope. Writing new blogs, extensive website copy, or large volumes of product content may require a separate quotation."
      },
      {
        "q": "Q10. Do you fix technical SEO issues directly?",
        "a": "We can implement agreed fixes where access and technical scope allow. Some issues require your website developer, hosting provider, or platform support. The quotation will clarify implementation responsibilities."
      },
      {
        "q": "Q11. What is Local SEO?",
        "a": "Local SEO focuses on improving the organisation and discoverability of business information and relevant website pages for location-related searches."
      },
      {
        "q": "Q12. What is Technical SEO?",
        "a": "Technical SEO examines factors such as crawlability, indexability, site structure, redirects, sitemaps, canonical URLs, mobile usability, and technical page experience."
      },
      {
        "q": "Q13. Do you provide backlink building?",
        "a": "We can assess a backlink profile and identify relevant, ethical opportunities where appropriate. Any outreach or link acquisition execution must be specifically included in the agreed scope. We do not promise a fixed number of links or ranking gains."
      },
      {
        "q": "Q14. Will I receive SEO reports?",
        "a": "Yes. Reporting is included according to the selected package. The report frequency, metrics, and scope will be documented in the quotation."
      },
      {
        "q": "Q15. Do I need to give you access to Google Search Console or Analytics?",
        "a": "Access to relevant tools can help us assess performance and technical issues. We will request only the access required for the agreed work, using supported permissions wherever possible."
      },
      {
        "q": "Q16. Can you do SEO for a newly launched website?",
        "a": "Yes. A new website can be assessed for technical foundations, structure, keyword planning, content requirements, and indexation readiness. New websites may take time to build search visibility."
      },
      {
        "q": "Q17. Can you help if my website traffic has declined?",
        "a": "We can assess available data, technical changes, content issues, and other possible contributing factors. A diagnosis depends on the information available, and recovery or ranking improvements cannot be guaranteed."
      },
      {
        "q": "Q18. Will SEO increase my sales?",
        "a": "SEO may help more relevant visitors discover your website, but sales depend on the offer, pricing, user experience, competition, trust, and conversion process. We cannot guarantee sales outcomes."
      },
      {
        "q": "Q19. Can SEO and social media be managed together?",
        "a": "Yes. They can be coordinated as part of an integrated digital marketing plan, although social media activity does not automatically result in higher organic search rankings."
      },
      {
        "q": "Q20. How do I choose between Orbit, Nova, and Cosmic?",
        "a": "The right package depends on website size, technical complexity, content needs, target market, implementation requirements, and reporting expectations. We can recommend a suitable scope after consultation."
      }
    ],
