    "faqs": [
      {
        "q": "Q1. What is Local SEO?",
        "a": "Local SEO helps businesses improve their visibility for relevant location-based searches. It can include business profile optimisation, local keywords, website improvements, location information consistency and useful local content."
      },
      {
        "q": "Q2. What is the difference between Local SEO and Local Digital Marketing?",
        "a": "Local SEO focuses on organic search visibility and relevant business information. Local digital marketing is broader and can include social media, paid advertising, content marketing and lead generation aimed at a defined geographic audience."
      },
      {
        "q": "Q3. Do I need a website for Local SEO?",
        "a": "Not every local activity requires a website, but a well-organised website can provide detailed service information, location pages and enquiry options. The right approach depends on your business and objectives."
      },
      {
        "q": "Q4. Can you create or optimise my Google Business Profile?",
        "a": "We can provide profile setup guidance and optimisation support where your business is eligible. Google controls verification, eligibility, approval, suspension decisions and display in search results."
      },
      {
        "q": "Q5. Can you guarantee that my business will appear first on Google Maps?",
        "a": "No. Local search results depend on factors such as relevance, distance, prominence and Google's systems. No service provider can guarantee a particular position."
      },
      {
        "q": "Q6. Is Local SEO suitable for businesses that serve customers at their locations?",
        "a": "Yes. Service-area businesses may be eligible for local search activities depending on their operating model and platform requirements. Business profiles must represent the business accurately and comply with applicable guidelines."
      },
      {
        "q": "Q7. Can you help a business that serves multiple cities?",
        "a": "Yes. We can assess your genuine service areas and recommend a suitable strategy. Dedicated location pages should offer meaningful, accurate information for each location rather than duplicate content created only to target keywords."
      },
      {
        "q": "Q8. Do you manage local advertising campaigns?",
        "a": "Local Google Ads and Meta Ads management can be included when agreed. Advertising budgets, account access, creative requirements and tracking arrangements will be defined in the proposal."
      },
      {
        "q": "Q9. Do you respond to customer reviews?",
        "a": "We can provide review-response guidance and draft responses within the agreed scope. Posting or responding directly requires the appropriate authorised access and must respect platform policies and customer privacy."
      },
      {
        "q": "Q10. How long does Local SEO take to show results?",
        "a": "Timelines vary by industry, competition, location, website condition and the work required. Some profile or website improvements can be completed relatively quickly, while search visibility changes may take longer. Results are not guaranteed."
      },
      {
        "q": "Q11. Can Local SEO generate calls and leads?",
        "a": "It can support discovery and provide clearer ways for customers to contact your business. Actual calls, enquiries and conversions depend on demand, competition, your offer, customer experience and other factors."
      },
      {
        "q": "Q12. Does the service include website development?",
        "a": "Not automatically. Website changes or new landing pages are included only when specified in the approved scope. Larger development tasks may require a separate quotation."
      },
      {
        "q": "Q13. Do you offer a service for small businesses with limited budgets?",
        "a": "Yes. The scope can be prioritised around the most relevant local opportunities and your available resources. We can recommend a suitable starting point after understanding your requirements."
      },
      {
        "q": "Q14. What information do you need to prepare a proposal?",
        "a": "We may ask for your business name, website, business category, operating locations, target audience, existing business profile and primary goals. Access to analytics or advertising accounts may be required for a more detailed review."
      },
      {
        "q": "Q15. How do I get a custom quotation?",
        "a": "Submit an enquiry through the form on this page. Our team will review your requirements and discuss a suitable scope before preparing a custom quotation."
      }
    ],
