    "faqs": [
      {
        "q": "Q1. What is lead generation?",
        "a": "Lead generation is the process of attracting potential customers and encouraging them to express interest through actions such as submitting an enquiry, requesting a quotation, booking a consultation or registering for an event."
      },
      {
        "q": "Q2. What is the difference between lead generation and conversion optimisation?",
        "a": "Lead generation focuses on attracting and capturing potential customers. Conversion optimisation focuses on improving the journey that helps visitors or leads take a desired action. The two can be planned together."
      },
      {
        "q": "Q3. Can you guarantee a fixed number of leads?",
        "a": "No. Lead volume and quality depend on market demand, offer relevance, competition, budget, targeting, landing page experience and other factors. We define the scope and agreed metrics without guaranteeing a specific outcome."
      },
      {
        "q": "Q4. Which platforms do you use for lead generation?",
        "a": "Depending on your business, the strategy may include Google Ads, Meta Ads, SEO, local search, social media, landing pages and other suitable channels. Platform selection follows the business requirements rather than a one-size-fits-all approach."
      },
      {
        "q": "Q5. Do you provide landing page design and development?",
        "a": "Landing page planning and optimisation recommendations can be included. Design and development are included only if specified in the approved quotation."
      },
      {
        "q": "Q6. Do you manage advertising budgets?",
        "a": "We can manage agreed campaigns, but advertising spend is generally paid to the relevant advertising platform and is separate from our service fee unless expressly agreed otherwise."
      },
      {
        "q": "Q7. What is a qualified lead?",
        "a": "A qualified lead is an enquiry that meets criteria agreed for your business, such as a relevant requirement, service location, business type or readiness to discuss a purchase. Qualification criteria differ by business."
      },
      {
        "q": "Q8. Do you provide CRM setup and automation?",
        "a": "We can plan lead management workflows and coordinate agreed CRM activities. Software subscriptions, custom integrations and implementation are scoped separately unless explicitly included."
      },
      {
        "q": "Q9. Can you help improve the quality of existing leads?",
        "a": "We can review available lead source data, campaign settings, enquiry forms and sales feedback to identify potential improvements. The impact depends on the evidence available and the changes implemented."
      },
      {
        "q": "Q10. Is this service suitable for B2B businesses?",
        "a": "Yes. The strategy can be tailored around target companies, decision-makers, consultation requests, quotation enquiries and the B2B sales process."
      },
      {
        "q": "Q11. How do you measure success?",
        "a": "Depending on your business and tracking setup, metrics may include enquiries, qualified leads, cost per lead, booking completion, conversion rate and lead-to-customer progression. The relevant metrics will be agreed before work begins."
      },
      {
        "q": "Q12. How long does it take to see results?",
        "a": "Timelines vary by channel, market, campaign setup, budget and sales process. Some campaigns can begin generating data shortly after launch, but reliable evaluation may require more time and sufficient data. Results are not guaranteed."
      },
      {
        "q": "Q13. Do you handle sales calls and close deals?",
        "a": "Sales calling, direct prospect follow-up and deal closing are not automatically included. These activities can be discussed separately if they are required and can be supported within an agreed scope."
      },
      {
        "q": "Q14. How do you handle customer information?",
        "a": "Lead collection and processing should follow applicable privacy requirements and the business's disclosed data-handling practices. Access to customer data should be restricted to authorised people and approved systems."
      },
      {
        "q": "Q15. How can I get a custom quotation?",
        "a": "Submit an enquiry with your business details, target audience and primary objectives. Our team will review your requirements and discuss a suitable scope before providing a custom quotation."
      }
    ],
