    "faqs": [
      {
        "q": "Q1. What is content marketing?",
        "a": "Content marketing involves planning, creating and distributing relevant content to attract and engage a defined audience. It can include blogs, website pages, social media posts, videos, guides and other useful resources."
      },
      {
        "q": "Q2. How is content marketing different from social media management?",
        "a": "Content marketing covers the broader strategy, creation and distribution of content across relevant channels. Social media management focuses on maintaining and managing a business's organic social media presence. The two can be coordinated when required."
      },
      {
        "q": "Q3. Does content marketing include SEO?",
        "a": "It can include SEO-focused research, content optimisation and planning when agreed. Technical SEO, extensive website changes and broader SEO implementation may require a separate scope."
      },
      {
        "q": "Q4. Can you create content for multiple platforms?",
        "a": "Yes. Content can be planned for websites, blogs, social media, YouTube, email and other suitable channels. The number of channels and deliverables will be defined in the quotation."
      },
      {
        "q": "Q5. Do you provide graphic design and video editing?",
        "a": "These services can be integrated where required, but design, photography, filming, animation and editing are included only when specified in the approved scope."
      },
      {
        "q": "Q6. Can AI be used to create content?",
        "a": "AI tools may support research, outlining and drafting. Final content should be reviewed for factual accuracy, originality, relevance, tone and compliance with applicable platform policies."
      },
      {
        "q": "Q7. How often should a business publish content?",
        "a": "There is no universal publishing frequency. The right schedule depends on your audience, content goals, available resources and the quality of content you can maintain consistently."
      },
      {
        "q": "Q8. How long does content marketing take to show results?",
        "a": "Timelines vary by channel, competition, content quality, publishing consistency and audience response. Content marketing is generally an ongoing activity, and specific outcomes cannot be guaranteed."
      },
      {
        "q": "Q9. Can content marketing generate leads?",
        "a": "Content can help educate potential customers and support enquiries when connected with relevant offers and conversion pathways. Lead volume depends on audience demand, content relevance, distribution and other factors."
      },
      {
        "q": "Q10. Do you publish content on our accounts?",
        "a": "Publishing and account access are included only if specified in the agreed scope. We will clarify whether E-COMET creates content for handover or also manages publishing."
      },
      {
        "q": "Q11. Do you provide content calendars?",
        "a": "Content calendars can be included to organise topics, formats, channels and planned publishing dates. The level of detail and review frequency will depend on the selected package."
      },
      {
        "q": "Q12. Can you work with our existing content?",
        "a": "Yes. Existing content can be reviewed, updated, reorganised or repurposed where suitable and where the necessary materials and access are provided."
      },
      {
        "q": "Q13. How do you measure content performance?",
        "a": "Depending on the channel and available analytics, measurement may include reach, engagement, website visits, organic search activity, enquiries and other agreed indicators. These metrics should be interpreted according to the content's purpose."
      },
      {
        "q": "Q14. Are advertising costs included?",
        "a": "Paid advertising spend is separate from content marketing fees unless expressly included in the quotation. Paid campaign management can be discussed as an additional service."
      },
      {
        "q": "Q15. How can I get a custom quotation?",
        "a": "Submit an enquiry with your business details, target audience, preferred channels and content requirements. Our team will review your needs and discuss a suitable scope before providing a custom quotation."
      }
    ],
