    "faqs": [
      {
        "q": "Q1. What is email marketing?",
        "a": "Email marketing is the planned use of email to communicate with eligible subscribers, prospects, and customers through campaigns, newsletters, automated sequences, and other relevant messages."
      },
      {
        "q": "Q2. Which businesses need email marketing?",
        "a": "Startups, e-commerce stores, B2B companies, service providers, retailers, educational institutions, and established brands may benefit when email suits their audience and communication goals."
      },
      {
        "q": "Q3. Can E-COMET create email campaigns for my business?",
        "a": "Yes. We can plan and create agreed campaign content, templates, audience segments, and deployment workflows based on your requirements and selected platform."
      },
      {
        "q": "Q4. Do I need an existing email subscriber list?",
        "a": "Not necessarily. We can discuss suitable opt-in subscriber collection methods, such as website forms and consent-based sign-up opportunities. We do not recommend buying lists or sending unsolicited bulk emails."
      },
      {
        "q": "Q5. Can you automate welcome emails and follow-ups?",
        "a": "Yes, where the selected platform and available integrations support the required workflow. Automation scope, triggers, testing, and data requirements are confirmed before implementation."
      },
      {
        "q": "Q6. Can email marketing help generate leads?",
        "a": "Email can support lead nurturing and encourage recipients to take a relevant action. Actual lead generation depends on audience quality, offer relevance, consent, campaign execution, and the wider sales process. Specific results cannot be guaranteed."
      },
      {
        "q": "Q7. Can you manage email marketing for Shopify or WooCommerce stores?",
        "a": "We can assess the store, selected email platform, available customer data, and integration requirements before recommending a suitable setup."
      },
      {
        "q": "Q8. Which email marketing platforms do you work with?",
        "a": "The suitable platform depends on your requirements, budget, existing systems, contact volume, automation needs, and regional availability. We confirm platform compatibility and scope during consultation rather than assuming every feature is available on every platform."
      },
      {
        "q": "Q9. Will my emails always reach the inbox?",
        "a": "No provider can guarantee inbox placement. Authentication, sender reputation, subscriber engagement, message content, and mailbox-provider rules can affect deliverability."
      },
      {
        "q": "Q10. Do you guarantee open rates, clicks, sales, or conversions?",
        "a": "No. We focus on structured execution, relevant communication, reporting, and ongoing improvement. Outcomes depend on many factors outside our control."
      },
      {
        "q": "Q11. How often should my business send emails?",
        "a": "The right frequency depends on your audience, business model, content value, subscriber expectations, and engagement signals. We help plan a suitable schedule rather than applying the same frequency to every business."
      },
      {
        "q": "Q12. Do your packages include email marketing software fees?",
        "a": "Not by default. Platform subscriptions, premium templates, integrations, and third-party charges are listed separately unless the quotation specifically states otherwise."
      },
      {
        "q": "Q13. Can you improve my existing email campaigns?",
        "a": "Yes. Subject to access and available data, we can review campaign structure, copy, templates, segmentation, technical setup, and performance indicators before recommending improvements."
      },
      {
        "q": "Q14. Do you follow email privacy and anti-spam requirements?",
        "a": "We plan campaigns around consent, appropriate subscriber permissions, unsubscribe handling, data minimisation, and applicable email marketing rules. The business remains responsible for the lawful basis and accuracy of its contact data; legal advice should be obtained when needed."
      },
      {
        "q": "Q15. How do I get started?",
        "a": "Submit an enquiry describing your business, audience, current email setup, and goals. Our team can review your requirements and discuss a suitable service scope and custom quotation."
      }
    ],
