    "faqs": [
      {
        "q": "Q1. What are SMS campaigns?",
        "a": "SMS campaigns are planned text-message communications used to share promotional offers, announcements, reminders, or other relevant information with appropriate recipients."
      },
      {
        "q": "Q2. What is the difference between promotional SMS and transactional SMS?",
        "a": "Promotional SMS is generally used for marketing messages, while transactional or service-related SMS communicates information connected to a transaction or service. Their permitted use, sender requirements, templates, and delivery rules can differ by jurisdiction and provider."
      },
      {
        "q": "Q3. Can E-COMET manage bulk SMS campaigns?",
        "a": "We can help plan and coordinate campaigns through a suitable provider, subject to provider capabilities, approved sender setup, recipient permissions, applicable regulations, and the agreed scope."
      },
      {
        "q": "Q4. Do I need an existing contact list?",
        "a": "Not necessarily. We can discuss suitable, consent-based methods for collecting contact information. We do not recommend purchased or scraped lists for unsolicited bulk messaging."
      },
      {
        "q": "Q5. Can SMS campaigns include links?",
        "a": "Yes, where supported by the provider and permitted under the relevant rules. Links should lead to appropriate, secure destinations and clearly relate to the message. Link tracking may require additional configuration."
      },
      {
        "q": "Q6. Can SMS messages be automated?",
        "a": "Yes, when the selected platform and integrations support the required triggers and workflows. Examples include eligible appointment reminders, enquiry acknowledgements, and selected customer notifications."
      },
      {
        "q": "Q7. Can you send SMS messages to customers across India?",
        "a": "Coverage and permitted messaging depend on the provider, sender registration, message classification, recipient network, and applicable Indian telecom and messaging requirements. We assess these factors before confirming the scope."
      },
      {
        "q": "Q8. Are SMS gateway or message-credit charges included in your packages?",
        "a": "Not by default. Provider fees, message credits, registration charges, applicable taxes, and other third-party costs are separate unless the quotation explicitly includes them."
      },
      {
        "q": "Q9. Can you guarantee message delivery?",
        "a": "No. Delivery can be affected by provider routing, network availability, recipient settings, sender configuration, message approval, and regulatory requirements."
      },
      {
        "q": "Q10. Can SMS campaigns increase sales?",
        "a": "SMS can support promotions, customer communication, and conversion journeys, but actual sales depend on factors such as the offer, audience, timing, landing page, pricing, and customer demand. Sales results cannot be guaranteed."
      },
      {
        "q": "Q11. How often should I send promotional SMS?",
        "a": "Frequency should be based on customer expectations, consent, campaign relevance, applicable rules, and opt-out signals. We help plan an appropriate schedule for your business."
      },
      {
        "q": "Q12. Do you provide the SMS software or gateway?",
        "a": "We can help assess and coordinate a suitable third-party provider. Platform access, subscriptions, credits, and technical capabilities depend on the selected provider and agreed scope."
      },
      {
        "q": "Q13. Can you integrate SMS with my CRM or online store?",
        "a": "Potentially, subject to the CRM or store platform, available integrations, API access, data permissions, and technical requirements. Any development or integration work will be scoped separately where necessary."
      },
      {
        "q": "Q14. Do SMS campaigns require customer consent?",
        "a": "Requirements depend on message type, recipient location, applicable laws, and provider rules. We plan campaigns around appropriate permissions, relevant registration and template requirements, and opt-out handling. Businesses must ensure their contact data and messaging practices comply with applicable rules."
      },
      {
        "q": "Q15. How can I get started?",
        "a": "Submit an enquiry with your business details, campaign objective, approximate audience size, and current messaging setup. We will review your requirements and discuss a suitable approach and custom quotation."
      }
    ],
