    "faqs": [
      {
        "q": "Q1. What is WhatsApp marketing?",
        "a": "WhatsApp marketing involves using supported WhatsApp business tools to communicate with customers, share relevant updates, coordinate promotional campaigns, handle enquiries, and support customer journeys."
      },
      {
        "q": "Q2. What is the difference between WhatsApp Business and the WhatsApp Business Platform?",
        "a": "The WhatsApp Business app is generally designed for businesses managing conversations through the app's available features. The WhatsApp Business Platform supports more advanced business messaging and integrations, subject to eligibility, setup, and platform rules."
      },
      {
        "q": "Q3. Can E-COMET help set up WhatsApp Business?",
        "a": "Yes. We can assist with profile setup or optimisation, messaging strategy, standard responses, catalogue guidance, and other agreed activities supported by the selected product."
      },
      {
        "q": "Q4. Can you run promotional WhatsApp campaigns?",
        "a": "We can plan and coordinate promotional campaigns for eligible recipients, subject to customer permissions, message-template requirements, platform rules, and the agreed scope."
      },
      {
        "q": "Q5. Can WhatsApp messages be automated?",
        "a": "Yes, selected workflows can be automated through supported platform features or integrations. Available triggers, templates, automation functions, and human handover options depend on the chosen solution."
      },
      {
        "q": "Q6. Can you build a WhatsApp chatbot?",
        "a": "We can assess and scope chatbot workflows based on your requirements. Advanced chatbot development, AI integration, custom APIs, and CRM connections may require a separate technical quotation."
      },
      {
        "q": "Q7. Can WhatsApp help generate leads?",
        "a": "WhatsApp can support enquiries and lead follow-ups, including eligible click-to-WhatsApp advertising. Actual lead volume and quality depend on the offer, audience, campaign setup, response process, and other factors. Results are not guaranteed."
      },
      {
        "q": "Q8. Can I send promotional messages to all my contacts?",
        "a": "No. Businesses must follow applicable permission requirements, WhatsApp policies, recipient preferences, and other relevant rules. Having someone's phone number does not automatically mean they have agreed to receive promotional WhatsApp messages."
      },
      {
        "q": "Q9. Do I need the WhatsApp Business Platform API?",
        "a": "Not necessarily. The right solution depends on your business size, message workflows, number of users, automation needs, integrations, and available features. We can review your requirements before recommending a setup."
      },
      {
        "q": "Q10. Are WhatsApp API and messaging charges included in your packages?",
        "a": "Not by default. Platform or provider fees, message charges where applicable, software subscriptions, and technical integration costs are separate unless specified in the quotation."
      },
      {
        "q": "Q11. Can you integrate WhatsApp with my website or CRM?",
        "a": "Potentially, subject to the website or CRM platform, supported integrations, account eligibility, permissions, and technical access. Development and integration requirements are assessed separately where necessary."
      },
      {
        "q": "Q12. Can you manage customer conversations for my business?",
        "a": "Conversation management can be included if agreed in the quotation. The scope must specify operating hours, expected volume, response responsibilities, escalation procedures, and whether E-COMET or your team will handle incoming messages."
      },
      {
        "q": "Q13. Can you guarantee more sales through WhatsApp marketing?",
        "a": "No. We can help plan campaigns and improve communication workflows, but sales depend on factors such as product-market fit, pricing, customer demand, message relevance, and the sales process."
      },
      {
        "q": "Q14. Do WhatsApp marketing messages require customer consent?",
        "a": "Businesses must follow the applicable WhatsApp policies and relevant legal requirements, including permission requirements for business-initiated messaging. Template approval and other conditions may also apply. The exact requirements depend on the use case and current platform rules."
      },
      {
        "q": "Q15. How do I get started?",
        "a": "Submit your business details, current WhatsApp setup, intended campaign type, and primary objective. Our team will review your requirements and discuss a suitable plan and custom quotation."
      }
    ],
