    "faqs": [
      {
        "q": "Q1. What is influencer marketing?",
        "a": "Influencer marketing involves collaborating with content creators who have an audience relevant to a business, product, or service. Campaigns may include sponsored posts, videos, demonstrations, and other agreed content."
      },
      {
        "q": "Q2. What is affiliate marketing?",
        "a": "Affiliate marketing is a performance-based arrangement in which approved partners promote products or services using trackable links, codes, or other agreed methods and may receive commissions for qualifying actions."
      },
      {
        "q": "Q3. What is partnership marketing?",
        "a": "Partnership marketing involves businesses or organisations collaborating on campaigns, referrals, co-branded activities, content, events, or other initiatives with shared objectives."
      },
      {
        "q": "Q4. How are the three services different?",
        "a": "Influencer marketing focuses on creator-led content and audience access. Affiliate marketing focuses on trackable referrals and agreed compensation. Partnership marketing focuses on broader collaboration between complementary businesses or organisations."
      },
      {
        "q": "Q5. Can E-COMET find influencers for my brand?",
        "a": "We can research and shortlist potential creators based on your requirements and available information. Their availability, interest, commercial rates, and final participation must be confirmed."
      },
      {
        "q": "Q6. Do you guarantee influencer reach or sales?",
        "a": "No. Creator performance, audience response, content distribution, and sales depend on multiple factors. We focus on appropriate selection, campaign coordination, and performance review."
      },
      {
        "q": "Q7. Do you work with micro-influencers?",
        "a": "We can explore micro-influencers and niche creators where they suit your audience, category, campaign objectives, and budget."
      },
      {
        "q": "Q8. Can you manage an affiliate programme from the beginning?",
        "a": "We can help plan the programme structure, recruitment approach, tracking requirements, commission rules, partner guidelines, and reporting process. Technical implementation depends on the selected platform and agreed scope."
      },
      {
        "q": "Q9. How are affiliate commissions decided?",
        "a": "Commission terms depend on product margins, qualifying actions, attribution rules, cancellations, returns, and the business's commercial objectives. The business approves the final commission structure."
      },
      {
        "q": "Q10. Can you help create co-branded campaigns?",
        "a": "Yes. We can support concept development, partner outreach, campaign briefs, responsibilities, creative coordination, and performance measurement, subject to partner agreement."
      },
      {
        "q": "Q11. Who pays influencer fees and affiliate commissions?",
        "a": "The responsible party and payment process are agreed before the campaign launches. Creator fees, affiliate commissions, product costs, and other third-party expenses are separate unless the quotation expressly includes them."
      },
      {
        "q": "Q12. Can influencer content be used in paid advertising?",
        "a": "Potentially, provided the creator or rights holder grants the required permissions and the proposed use complies with platform rules, applicable law, and the agreed licence. Organic posting rights do not automatically include paid advertising usage rights."
      },
      {
        "q": "Q13. Do sponsored collaborations require disclosure?",
        "a": "Sponsored content and other material commercial relationships may require clear disclosure under applicable advertising rules and platform policies. Requirements depend on the content, jurisdiction, and arrangement. We help include appropriate disclosure considerations in the campaign brief."
      },
      {
        "q": "Q14. Can these services work for B2B businesses?",
        "a": "Yes. B2B businesses may explore expert collaborations, industry partnerships, referral programmes, affiliate arrangements, webinars, and collaborative content when suitable for their audience."
      },
      {
        "q": "Q15. How do you measure campaign performance?",
        "a": "Depending on the campaign, we may review reach, engagement, clicks, referral traffic, enquiries, recorded conversions, coupon usage, and other relevant indicators. Tracking availability and attribution limitations are documented where applicable."
      },
      {
        "q": "Q16. How do I get started?",
        "a": "Submit an enquiry describing your business, target audience, campaign objective, and preferred collaboration model. We will review your requirements and discuss a suitable scope and custom quotation."
      }
    ],
