    "faqs": [
      {
        "q": "Q1. What is Marketing Analytics & Automation?",
        "a": "Marketing Analytics is the process of measuring and interpreting marketing data. Marketing Automation uses configured workflows to perform selected repetitive tasks, such as sending permitted emails, assigning leads, or creating reminders."
      },
      {
        "q": "Q2. Is this service suitable for a small business?",
        "a": "Yes. A small business may begin with a basic measurement plan, selected tracking, a simple dashboard, or a structured lead follow-up workflow. The recommended scope depends on its goals and existing setup."
      },
      {
        "q": "Q3. Which tools do you use?",
        "a": "Tool selection depends on the project. Potential tools include Google Analytics 4, Google Tag Manager, Looker Studio, spreadsheets, CRM platforms, email marketing systems, and supported automation tools."
      },
      {
        "q": "Q4. Do I need a CRM before starting?",
        "a": "No. We can first review your requirements and help assess whether a CRM is appropriate. A simple workflow or spreadsheet may be sufficient for some businesses, while others may benefit from a dedicated CRM."
      },
      {
        "q": "Q5. Can you connect my website, ads, and CRM?",
        "a": "Potentially, where the selected platforms support the required integration and the necessary permissions are available. Compatibility, data access, technical effort, and third-party costs must be reviewed before confirming the scope."
      },
      {
        "q": "Q6. Can automation guarantee more leads or sales?",
        "a": "No. Automation can help organise processes and reduce selected manual tasks, but it cannot guarantee lead volume, sales, revenue, or profitability. Results also depend on the offer, audience, market, sales process, and other factors."
      },
      {
        "q": "Q7. Can you track every customer who visits my website?",
        "a": "Not necessarily. Consent choices, browser restrictions, privacy settings, ad blockers, and technical limitations can affect tracking. We implement measurement within applicable rules and the capabilities of the chosen tools."
      },
      {
        "q": "Q8. Can you calculate ROAS and marketing ROI?",
        "a": "We can calculate and report ROAS where reliable advertising cost and attributed revenue data are available. ROI requires a suitable definition of costs and returns. ROAS and ROI are different metrics, and neither automatically represents net profit."
      },
      {
        "q": "Q9. Do you provide real-time dashboards?",
        "a": "Some tools support near-real-time or frequent updates, while others update on a schedule or depend on data-source limits. Refresh frequency will be confirmed for the chosen setup."
      },
      {
        "q": "Q10. Can you automate WhatsApp messages?",
        "a": "Certain workflows may be possible through supported WhatsApp Business tools and approved integrations. The available functionality depends on the selected setup, platform policies, permissions, applicable consent requirements, and any relevant messaging charges."
      },
      {
        "q": "Q11. Do I need to purchase software separately?",
        "a": "Possibly. Paid CRM plans, analytics connectors, automation platforms, email services, API usage, and other subscriptions may have separate charges. These will be identified where known before the work is approved."
      },
      {
        "q": "Q12. Will E-COMET manage the system after implementation?",
        "a": "Ongoing monitoring, troubleshooting, reporting, and optimisation can be included in a suitable service agreement. The exact support period and responsibilities will be confirmed in your proposal."
      },
      {
        "q": "Q13. How long does implementation take?",
        "a": "The timeline depends on the number of tools, tracking events, workflows, integrations, access permissions, and technical dependencies. A timeline will be proposed after reviewing the requirements."
      },
      {
        "q": "Q14. What access do you need?",
        "a": "Depending on the project, we may need appropriate permissions for your website analytics, tag manager, advertising platforms, CRM, reporting tools, or automation systems. Access should be granted securely using suitable role-based permissions rather than shared passwords."
      },
      {
        "q": "Q15. How can I get a quotation?",
        "a": "Submit the enquiry form with your business type, goals, existing tools, and key requirements. Our team can review the information and discuss a suitable scope before providing a custom quotation."
      }
    ],
